// يضع النص الأولي لسياسة الخصوصية والشروط في Firestore إن لم يكن موجوداً،
// ولا يلمس أي نص عدّله الأدمن بعد ذلك من لوحة التحكم.
import { createSign } from "node:crypto";

const PROJECT = "melz-restaurant";
const DOCS = `https://firestore.googleapis.com/v1/projects/${PROJECT}/databases/(default)/documents`;

const fail = (msg) => {
  console.log(`::error::${String(msg).replace(/\r?\n/g, " ").slice(0, 1500)}`);
  process.exit(1);
};

async function accessToken(sa) {
  const b64 = (v) => Buffer.from(v).toString("base64url");
  const now = Math.floor(Date.now() / 1000);
  const unsigned = `${b64(JSON.stringify({ alg: "RS256", typ: "JWT" }))}.${b64(
    JSON.stringify({
      iss: sa.client_email,
      scope: "https://www.googleapis.com/auth/datastore",
      aud: "https://oauth2.googleapis.com/token",
      iat: now,
      exp: now + 600,
    })
  )}`;
  const signature = createSign("RSA-SHA256").update(unsigned).sign(sa.private_key, "base64url");
  const res = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    body: new URLSearchParams({
      grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
      assertion: `${unsigned}.${signature}`,
    }),
  });
  if (!res.ok) fail(`auth: ${await res.text()}`);
  return (await res.json()).access_token;
}

